+class EqlFunctionDefinition extends FunctionDefinition {
+
+    private final boolean caseAware;
+
+    protected EqlFunctionDefinition(String name,
+                                    List<String> aliases,
+                                    Class<? extends Function> clazz,
+                                    boolean caseAware,
