+import static org.elasticsearch.xpack.ql.expression.gen.script.ParamsBuilder.paramsBuilder;
+
+public abstract class BinaryComparisonCaseInsensitiveFunction extends CaseInsensitiveScalarFunction {
+
+    private final Expression left, right;
+
+    protected BinaryComparisonCaseInsensitiveFunction(Source source, Expression left, Expression right, boolean caseSensitive) {
+        super(source, asList(left, right), caseSensitive);
+        this.left = left;
+        this.right = right;
+    }
+
+    @Override
+    protected TypeResolution resolveType() {
+        if (childrenResolved() == false) {
+            return new TypeResolution("Unresolved children");
+        }
+
+        TypeResolution sourceResolution = isStringAndExact(left, sourceText(), ParamOrdinal.FIRST);
+        if (sourceResolution.unresolved()) {
+            return sourceResolution;
+        }
+
+        return isStringAndExact(right, sourceText(), ParamOrdinal.SECOND);
+    }
+
+    public Expression left() {
+        return left;
+    }
+
+    public Expression right() {
+        return right;
+    }
+
+    @Override
+    public DataType dataType() {
+        return DataTypes.BOOLEAN;
+    }
+
+
+    @Override
+    public boolean foldable() {
+        return left.foldable() && right.foldable();
+    }
+
+    @Override
+    public ScriptTemplate asScript() {
+        ScriptTemplate leftScript = asScript(left);
+        ScriptTemplate rightScript = asScript(right);
+
+        return asScriptFrom(leftScript, rightScript);
+    }
+
+    protected ScriptTemplate asScriptFrom(ScriptTemplate leftScript, ScriptTemplate rightScript) {
+        return new ScriptTemplate(format(Locale.ROOT, formatTemplate("%s.%s(%s,%s,%s)"),
+            Scripts.classPackageAsPrefix(getClass()),
+            scriptMethodName(),
+            leftScript.template(),
+            rightScript.template(),
+            "{}"),
+            paramsBuilder()
+                .script(leftScript.params())
+                .script(rightScript.params())
+                .variable(isCaseInsensitive())
+                .build(), dataType());
+    }
+
+    protected String scriptMethodName() {
+        String simpleName = getClass().getSimpleName();
+        return Character.toLowerCase(simpleName.charAt(0)) + simpleName.substring(1);
+    }
+
+    @Override
+    public int hashCode() {
+        return Objects.hash(left, right, isCaseInsensitive());
+    }
+
+    @Override
+    public boolean equals(Object obj) {
+        if (this == obj) {
+            return true;
+        }
+
+        if (obj == null || getClass() != obj.getClass()) {
+            return false;
+        }
+
+        BinaryComparisonCaseInsensitiveFunction other = (BinaryComparisonCaseInsensitiveFunction) obj;
+        return Objects.equals(left, other.left)
+            && Objects.equals(right, other.right)
+            && Objects.equals(isCaseInsensitive(), other.isCaseInsensitive());
+    }
+}

